const { parse } = require('@babel/parser');

const samples = [
  'function f(x { return x + 1; }',       // missing )
  'function g(x) { return x + 1;',         // missing }
  "const s = 'unterminated",                // missing closing quote
];

for (const src of samples) {
  const ast = parse(src, { errorRecovery: true });
  console.log(src, '=>', ast.errors.map((e) => e.reasonCode));
}
